#!/usr/bin/env node
// Downloads the static font files the caption templates use into public/fonts
// and writes two generated files from them:
//   lib/captions/engine/font-manifest.json   family/weight/italic → file + exact names
//   app/components/captions/caption-fonts.css  @font-face rules for the live previews
//
// Why static instances: libass renders a variable font at its default instance
// only, so "Montserrat 900" from a variable file would come out regular. Asking
// the Google Fonts CSS API with an old user agent returns one static TrueType
// file per weight/style, which is what libass (render) and fontkit (layout) need.
//
// Every font here is SIL Open Font License except Permanent Marker and Chewy (Apache 2.0);
// see public/fonts/LICENSES.md. Re-run after adding a font to a template:
//   node scripts/sync-caption-fonts.mjs

import fs from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";
import * as fontkit from "fontkit";

const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..");
const FONT_DIR = path.join(ROOT, "public", "fonts");
const MANIFEST = path.join(ROOT, "lib", "captions", "engine", "font-manifest.json");
const CSS_OUT = path.join(ROOT, "app", "components", "captions", "caption-fonts.css");
// A non-browser user agent: the CSS API then serves TrueType rather than WOFF/WOFF2.
const OLD_UA = "Wget/1.21";

// [family, weights, italic weights]
const FONTS = [
  ["Montserrat", [700, 800, 900], [900]],
  ["Anton", [400], []],
  ["Archivo Black", [400], []],
  ["Bebas Neue", [400], []],
  ["Rubik", [800, 900], []],
  ["Poppins", [600, 700, 800], []],
  ["Unbounded", [700], []],
  ["Space Grotesk", [700], []],
  ["Fredoka", [700], []],
  ["Barlow Condensed", [700], []],
  ["Barlow", [700, 800], []],
  ["Lilita One", [400], []],
  ["Manrope", [700], []],
  ["Bangers", [400], []],
  ["Permanent Marker", [400], []],
  ["Caveat", [700], []],
  ["Baloo 2", [800], []],
  ["Nunito", [900], []],
  ["Inter", [500, 700, 800], []],
  ["Inter Tight", [800], []],
  ["Plus Jakarta Sans", [700], []],
  ["DM Sans", [500, 800], []],
  ["Outfit", [300], []],
  ["Cormorant Garamond", [600], []],
  ["Cinzel", [700], []],
  ["Playfair Display", [700], [700]],
  ["Syne", [800], []],
  ["Instrument Serif", [], [400]],
  ["DM Serif Display", [400], [400]],
  ["Press Start 2P", [400], []],
  ["Righteous", [400], []],
  ["VT323", [400], []],
  ["Mukta", [800], []],
  ["Rozha One", [400], []],
  // Drop 1 of templates 51-150
  ["Dela Gothic One", [400], []],
  ["Bungee", [400], []],
  ["Sora", [800], []],
  ["Chewy", [400], []],
  ["Bowlby One", [400], []],
  ["Lexend", [800], []],
];

function fileNameFor(family, weight, italic) {
  return `${family.replace(/\s+/g, "")}-${weight}${italic ? "i" : ""}.ttf`;
}

async function fetchTtfUrl(family, weight, italic) {
  const axis = italic ? `ital,wght@1,${weight}` : `wght@${weight}`;
  const url = `https://fonts.googleapis.com/css2?family=${encodeURIComponent(family).replace(/%20/g, "+")}:${axis}`;
  const res = await fetch(url, { headers: { "User-Agent": OLD_UA } });
  if (!res.ok) throw new Error(`${family} ${weight}${italic ? "i" : ""}: CSS ${res.status}`);
  const css = await res.text();
  const m = css.match(/url\((https:[^)]+\.ttf)\)/);
  if (!m) throw new Error(`${family} ${weight}: no TrueType url in CSS`);
  return m[1];
}

const manifest = [];
for (const [family, weights, italics] of FONTS) {
  const variants = [...weights.map((w) => [w, false]), ...italics.map((w) => [w, true])];
  for (const [weight, italic] of variants) {
    const file = fileNameFor(family, weight, italic);
    const dest = path.join(FONT_DIR, file);
    if (!fs.existsSync(dest)) {
      const ttfUrl = await fetchTtfUrl(family, weight, italic);
      const res = await fetch(ttfUrl);
      if (!res.ok) throw new Error(`${file}: download ${res.status}`);
      fs.writeFileSync(dest, Buffer.from(await res.arrayBuffer()));
      process.stdout.write(`downloaded ${file}\n`);
    }
    const font = fontkit.openSync(dest);
    if (font.variationAxes && Object.keys(font.variationAxes).length) {
      throw new Error(`${file} is a variable font; libass would render only its default instance`);
    }
    manifest.push({
      family,
      weight,
      italic,
      file,
      fullName: font.fullName,
      postscriptName: font.postscriptName,
      devanagari: font.hasGlyphForCodePoint(0x0915),
    });
  }
}

fs.mkdirSync(path.dirname(MANIFEST), { recursive: true });
fs.writeFileSync(MANIFEST, JSON.stringify(manifest, null, 2) + "\n");

const css = [
  "/* Generated by scripts/sync-caption-fonts.mjs: do not edit. */",
  ...manifest.map((f) =>
    `@font-face{font-family:"${f.family}";src:url("/fonts/${f.file}") format("truetype");font-weight:${f.weight};font-style:${f.italic ? "italic" : "normal"};font-display:swap}`,
  ),
].join("\n");
fs.mkdirSync(path.dirname(CSS_OUT), { recursive: true });
fs.writeFileSync(CSS_OUT, css + "\n");
process.stdout.write(`${manifest.length} font files, manifest + css written\n`);
